        locators: [
          { kind: "name", value: "web" },
          { kind: "git-branch", value: "feature/remote-agents-web" },
          { kind: "repository", value: "github.com/acme/web" },
        ],
        repositoryIdentity,
        firstSeenAt: seenAt,
        lastSeenAt: seenAt,
