describe("TwsBindingMatch", () => {
  it("matches by retained locator and merges a rename under the same product id", () => {
    const id = TwsWorkspaceBindingId.make("workspace-binding-1");
    const existing = {
      id,
      canonicalLocator: { kind: "path" as const, value: "/old/path" },
      locators: [{ kind: "registry-entry" as const, value: "registry-1" }],
    };

    assert.deepEqual(
      matchTwsBindingByLocators(
        [existing],
        [
          { kind: "registry-entry", value: "registry-1" },
          { kind: "path", value: "/new/path" },
        ],
      ),
      { kind: "matched", id },
    );
    assert.deepEqual(
      mergeTwsLocators({ kind: "path", value: "/new/path" }, existing.locators, [
        existing.canonicalLocator,
      ]),
      [
        { kind: "path", value: "/new/path" },
        { kind: "registry-entry", value: "registry-1" },
        { kind: "path", value: "/old/path" },
      ],
    );
  });

  it("returns new or ambiguous without consulting repository identity", () => {
    assert.deepEqual(matchTwsBindingByLocators([], [{ kind: "name", value: "feature-a" }]), {
      kind: "new",
    });

    const observed = [{ kind: "name" as const, value: "feature-a" }];
    const bindings = ["binding-b", "binding-a"].map((value) => ({
      id: TwsWorkspaceBindingId.make(value),
      canonicalLocator: observed[0]!,
      locators: observed,
      repositoryIdentity: value,
    }));
    assert.deepEqual(matchTwsBindingByLocators(bindings, observed), {
      kind: "ambiguous",
      ids: [TwsWorkspaceBindingId.make("binding-a"), TwsWorkspaceBindingId.make("binding-b")],
    });
  });
});

import { TWS_BINDING_MAX_LOCATORS, type TwsLocator } from "@t3tools/contracts";

export type TwsBindingMatch<Id extends string> =
  | { readonly kind: "new" }
  | { readonly kind: "matched"; readonly id: Id }
  | { readonly kind: "ambiguous"; readonly ids: ReadonlyArray<Id> };

function locatorKey(locator: TwsLocator): string {
  return `${locator.kind}\0${locator.value}`;
}

export function mergeTwsLocators(
  canonicalLocator: TwsLocator,
  ...collections: ReadonlyArray<ReadonlyArray<TwsLocator>>
): ReadonlyArray<TwsLocator> {
  const merged = new Map<string, TwsLocator>();
  merged.set(locatorKey(canonicalLocator), canonicalLocator);
  for (const locators of collections) {
    for (const locator of locators) {
      const key = locatorKey(locator);
      if (!merged.has(key)) {
        merged.set(key, locator);
      }
    }
  }
  return [...merged.values()].slice(0, TWS_BINDING_MAX_LOCATORS);
}

export function matchTwsBindingByLocators<Id extends string>(
  bindings: ReadonlyArray<{
    readonly id: Id;
    readonly canonicalLocator: TwsLocator;
    readonly locators: ReadonlyArray<TwsLocator>;
  }>,
  observedLocators: ReadonlyArray<TwsLocator>,
): TwsBindingMatch<Id> {
  const observed = new Set(observedLocators.map(locatorKey));
  const ids = [
    ...new Set(
      bindings.flatMap((binding) =>
        [binding.canonicalLocator, ...binding.locators].some((locator) =>
          observed.has(locatorKey(locator)),
        )
          ? [binding.id]
          : [],
      ),
    ),
  ].toSorted();

  if (ids.length === 0) {
    return { kind: "new" };
  }
  if (ids.length === 1) {
    return { kind: "matched", id: ids[0]! };
  }
  return { kind: "ambiguous", ids };
}

